mapper.update:

UPDATE 移行管理テーブル
SET ステータス = 'RUNNING',
    開始日時   = #{開始日時}
WHERE システム  = #{システム}
  AND 処理FROM  = #{処理FROM}


UPDATE 移行管理テーブル
SET ステータス = 'DONE',
    終了日時   = #{終了日時}
WHERE システム  = #{システム}
  AND 処理FROM  = #{処理FROM}


UPDATE 移行管理テーブル
SET ステータス = 'ERROR',
    終了日時   = #{終了日時},
    備考       = #{備考}
WHERE システム  = #{システム}
  AND 処理FROM  = #{処理FROM}
